def build_gold_v2(source=ENGINE_FIXTURES / "semantic_gold_v1.json"):
    base=json.loads(Path(source).read_text(encoding="utf-8"))["cases"]
    cases=list(base)
    for i,(title,entity,event_type,news,evergreen,language) in enumerate(SINGLES,1):
        cases.append({"id":f"v2s{i:02d}","kind":"single","language":language,"title":title,"description":title+".","expected":{"main_entity":None if entity=="None" else entity,"event_type":event_type,"is_news_event":news,"is_evergreen":evergreen,"is_analysis":event_type=="ANALYSIS","is_opinion":event_type=="OPINION","is_promotional":event_type=="PROMOTION"}})
    for i,(a,ea,b,eb,same) in enumerate(PAIRS,1):
        cases.append({"id":f"v2p{i:02d}","kind":"pair","language":"en","a":{"title":a,"description":a+"."},"b":{"title":b,"description":b+"."},"expected_same":same})
    return {"version":"semantic_gold_v2","cases":cases}

def write_gold_v2(path=ENGINE_FIXTURES / "semantic_gold_v2.json"):
    data=build_gold_v2(); Path(path).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding="utf-8"); return data

